// An arbitrary time value.
static constexpr nsecs_t ARBITRARY_TIME = 1234;

// An arbitrary device id.
static constexpr DeviceId DEVICE_ID = DEFAULT_DEVICE_ID;
static constexpr DeviceId SECOND_DEVICE_ID = 2;

